import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, PlaneGeometry, SphereGeometry, DirectionalLight, Color } = ctx.THREE;

  // Resolve visual spec tokens
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const ctaText = textItems.find(item => item.role === 'headline' || item.text)?.text ?? 'Get started';

  const container = new Group();

  // Create local polished backboard for the CTA (engineered plate)
  const plateWidth = 2.4;
  const plateHeight = 0.65;
  const plateDepth = 0.04;

  const plateGeo = new BoxGeometry(plateWidth, plateHeight, plateDepth);

  // Custom Node Material representing machined/brushed metal with gradient surface
  const plateMat = new MeshStandardNodeMaterial({
    roughness: 0.35,
    metalness: 0.75,
    clearcoat: 0.2,
    clearcoatRoughness: 0.1
  });

  // Load brushed metal map
  const imageUrl = config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.wrapS = tex.wrapT = 1000; // Repeat Wrapping
    plateMat.map = tex;
    plateMat.needsUpdate = true;
  });

  // Inject TSL engineered gradient to prevent flat black spots
  const baseGrad = mix(color(palette.surface), color(palette.ink), uv().y);
  plateMat.colorNode = baseGrad;

  const plateMesh = new Mesh(plateGeo, plateMat);
  container.add(plateMesh);

  // Subtle accent dot indicating active interaction potential
  const dotGeo = new SphereGeometry(0.02, 16, 16);
  const dotMat = new MeshStandardNodeMaterial({
    color: new Color(palette.accent),
    emissive: new Color(palette.accent),
    emissiveIntensity: 1.2,
    roughness: 0.1
  });
  const dotMesh = new Mesh(dotGeo, dotMat);
  dotMesh.position.set(-plateWidth / 2 + 0.18, 0, plateDepth / 2 + 0.01);
  container.add(dotMesh);

  // Load and apply Text
  const textObj = ctx.fontAtlas.createText(ctaText, {
    fontSize: 42,
    color: palette.paper,
    align: 'center'
  });
  // Position text directly in front of block
  textObj.position.set(0.08, -0.05, plateDepth / 2 + 0.01);
  textObj.scale.setScalar(0.0075);
  container.add(textObj);

  // local key/rim illumination to satisfy studio lighting requirements
  const localLight = new DirectionalLight(palette.paper, 1.2);
  localLight.position.set(2, 3, 4);
  container.add(localLight);

  const localRim = new DirectionalLight(palette.accent, 0.8);
  localRim.position.set(-2, -2, -1);
  container.add(localRim);

  // Cleanup procedure
  container.userData.cleanup = () => {
    plateGeo.dispose();
    plateMat.dispose();
    dotGeo.dispose();
    dotMat.dispose();
    localLight.dispose();
    localRim.dispose();
  };

  return container;
}
